#!/usr/bin/env bash
# ClouDNS DDNS A-record updater for bgssh.abrdns.com.
# Designed for a stable public HTTPS ingress host, NOT an ephemeral GitHub runner.
# CLOUDNS_DDNS_URL is a secret generated by ClouDNS for the A record.
set -euo pipefail

say() { printf '[BGSSH ClouDNS] %s\n' "$1"; }

# ClouDNS DynamicURL sets the record to the public IP of the CALLER.
# Always refuse on GitHub Actions, even if someone accidentally enables it.
if [[ "${GITHUB_ACTIONS:-false}" == "true" ]]; then
  say "SKIP: GitHub Actions has no stable public HTTPS ingress; DNS unchanged."
  exit 0
fi

if [[ "${BGSSH_DDNS_ENABLED:-0}" != "1" ]]; then
  say "SKIP: DDNS is not enabled; DNS unchanged."
  exit 0
fi

if [[ "${BGSSH_DDNS_PUBLIC_HTTPS_READY:-0}" != "1" ]]; then
  say "ERROR: public HTTPS ingress has not been confirmed; DNS unchanged."
  exit 1
fi

if [[ -z "${CLOUDNS_DDNS_URL:-}" || "$CLOUDNS_DDNS_URL" != https://ipv4.cloudns.net/api/dynamicURL/\?q=* ]]; then
  say "ERROR: configure the private ClouDNS IPv4 DynamicURL for this A record."
  exit 1
fi

# Avoid leaking a credential-bearing URL through command-line arguments or logs.
# The exact URL format comes from ClouDNS; reject unsafe shell/curl config chars.
token="${CLOUDNS_DDNS_URL#https://ipv4.cloudns.net/api/dynamicURL/?q=}"
if [[ ! "$token" =~ ^[A-Za-z0-9_.%~-]+$ ]]; then
  say "ERROR: unrecognized DynamicURL format; DNS unchanged."
  exit 1
fi

command -v curl >/dev/null 2>&1 || { say "ERROR: curl is missing."; exit 1; }
umask 077
reply="$(mktemp)"
trap 'rm -f "$reply"' EXIT

# A default DynamicURL update replies OK. Do not disable TLS verification.
if ! printf 'url = "%s"\n' "$CLOUDNS_DDNS_URL" |
  curl --config - --silent --fail --show-error --proto '=https' \
    --tlsv1.2 --connect-timeout 5 --max-time 20 --ipv4 --output "$reply" 2>/dev/null; then
  say "ERROR: ClouDNS HTTPS update request failed; no secret is logged."
  exit 1
fi

if [[ "$(tr -d '[:space:]' < "$reply")" != "OK" ]]; then
  say "ERROR: ClouDNS did not confirm OK; verify A-record DynamicURL."
  exit 1
fi

say "OK: requested A-record update from the HTTPS ingress host (DNS propagation may take time)."
